import { EP } from "../_client";
import { Routes } from "@angular/router";
import { Type } from "@angular/core";
import { MenuFeatureIndex } from "./menu-feature-index/menu-feature-index";


export class RoutezFeatureModule {
  private routes: Routes = [];
  constructor(
    private title: string,
    private routeModule: string,
  ) {
    this.addIndexRoute();
  }
  private addIndexRoute() {
    this.routes.push(
      {
        path: '',
        redirectTo: 'index',
        pathMatch: 'full',
      },
      {
        path: 'index',
        component: MenuFeatureIndex,
        data: {
          title: `${this.title} Module`,
          linkPaginate: ``,
          linkAdd: ``,
          linkUpdate: ``,
          permission: [EP.Add, EP.GetsPaginate],
        },
      }
    );
  }
  feature(
    listComponent: Type<any>,
    addComponent: Type<any>,
    path: string,
    title: string,
  ): this {

    this.routes.push(
      {
        path: `${path}-list`,
        component: listComponent,
        data: {
          title,
          linkPaginate: ``,
          linkAdd: `/${this.routeModule}/${path}-add`,
          linkUpdate: `/${this.routeModule}/${path}-edit/`,
          permission: [EP.GetsPaginate, EP.Add, EP.Update, EP.Delete],
        },
      },

      {
        path: `${path}-add`,
        component: addComponent,
        data: {
          title,
          linkPaginate: `/${this.routeModule}/${path}-list`,
          linkAdd: ``,
          linkUpdate: ``,
          permission: [EP.Get, EP.Add ],
        },
      },
      {
        path: `${path}-edit/:id`,
        component: addComponent,
        data: {
          title,
          linkPaginate: `/${this.routeModule}/${path}-list`,
          linkAdd: ``,
          linkUpdate: ``,
          permission: [EP.Get, EP.Update],
        },
      }
    );

    return this;
  }

  build(): Routes {
    return this.routes;
  }
}
